/**
 * Model User
 * Auth identity. Every login is a User with a role. Super admin has no society;
 * residents additionally have a flat; maintenance staff have a staffLabel.
 * 
 * Two ways in: phone+password (`password` set) or Firebase phone OTP
 * (`firebaseUid` set). Seeded users have only a password; users who first
 * arrive via OTP have only a firebaseUid — hence both are optional.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Society
 * 
 */
export type Society = $Result.DefaultSelection<Prisma.$SocietyPayload>
/**
 * Model Tower
 * 
 */
export type Tower = $Result.DefaultSelection<Prisma.$TowerPayload>
/**
 * Model Flat
 * 
 */
export type Flat = $Result.DefaultSelection<Prisma.$FlatPayload>
/**
 * Model Resident
 * Directory entry managed by the society admin (owner/tenant of a flat).
 */
export type Resident = $Result.DefaultSelection<Prisma.$ResidentPayload>
/**
 * Model Notice
 * 
 */
export type Notice = $Result.DefaultSelection<Prisma.$NoticePayload>
/**
 * Model SupportTicket
 * A support ticket a society admin raises; handled in the super-admin panel.
 */
export type SupportTicket = $Result.DefaultSelection<Prisma.$SupportTicketPayload>
/**
 * Model PlatformNotification
 * A notification the super-admin sent from the panel's Notification Center.
 * In-app is delivered via AppNotification; push/email are recorded here (real
 * delivery needs an FCM / email provider).
 */
export type PlatformNotification = $Result.DefaultSelection<Prisma.$PlatformNotificationPayload>
/**
 * Model LoginEvent
 * One row per successful login — powers the panel's login analytics.
 */
export type LoginEvent = $Result.DefaultSelection<Prisma.$LoginEventPayload>
/**
 * Model ContentPage
 * App content the super-admin edits without shipping an app update — FAQ,
 * legal pages, About/Contact. Keyed by a fixed slug.
 */
export type ContentPage = $Result.DefaultSelection<Prisma.$ContentPagePayload>
/**
 * Model PlatformSettings
 * Single-row platform settings, managed by the super-admin panel. Integration
 * keys are stored here; wiring them to real services is separate.
 */
export type PlatformSettings = $Result.DefaultSelection<Prisma.$PlatformSettingsPayload>
/**
 * Model AppConfig
 * Single-row app version config, managed by the super-admin panel and read by
 * the mobile app on launch to prompt / force updates.
 */
export type AppConfig = $Result.DefaultSelection<Prisma.$AppConfigPayload>
/**
 * Model FeatureFlag
 * A platform-wide feature toggle, flipped from the super-admin panel.
 */
export type FeatureFlag = $Result.DefaultSelection<Prisma.$FeatureFlagPayload>
/**
 * Model AuditLog
 * A record of an action the super-admin took in the web panel.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model AppNotification
 * An in-app notification for the society admin — e.g. a resident paid a bill.
 */
export type AppNotification = $Result.DefaultSelection<Prisma.$AppNotificationPayload>
/**
 * Model Bill
 * 
 */
export type Bill = $Result.DefaultSelection<Prisma.$BillPayload>
/**
 * Model Complaint
 * 
 */
export type Complaint = $Result.DefaultSelection<Prisma.$ComplaintPayload>
/**
 * Model Visitor
 * 
 */
export type Visitor = $Result.DefaultSelection<Prisma.$VisitorPayload>
/**
 * Model PreApprovedVisitor
 * 
 */
export type PreApprovedVisitor = $Result.DefaultSelection<Prisma.$PreApprovedVisitorPayload>
/**
 * Model Delivery
 * 
 */
export type Delivery = $Result.DefaultSelection<Prisma.$DeliveryPayload>
/**
 * Model Amenity
 * 
 */
export type Amenity = $Result.DefaultSelection<Prisma.$AmenityPayload>
/**
 * Model AmenityBooking
 * 
 */
export type AmenityBooking = $Result.DefaultSelection<Prisma.$AmenityBookingPayload>

